TLM.f("Tempora/Adv3-1",{"officium":"Feria II infra Hebdomadam III Adventus","rule":["Oratio Dominica","no Gloria","no Credo","Suffr=Maria1;Ecclesiæ,Papa;;"],"ruleInherited":["no Gloria","Credo","Suffr=Maria1;Ecclesiæ,Papa;;"],"fallback":"Tempora/Adv3-0","from":{"Introitus":"Tempora/Adv3-0","Oratio":"Tempora/Adv3-0","Lectio":"Tempora/Adv3-0","Graduale":"Tempora/Adv3-0","GradualeF":"Tempora/Adv3-0","Evangelium":"Tempora/Adv3-0","Offertorium":"Tempora/Adv3-0","Secreta":"Tempora/Adv3-0","Communio":"Tempora/Adv3-0","Postcommunio":"Tempora/Adv3-0"},"sections":{"Introitus":[{"k":"ref","la":"Phil 4:4-6"},{"k":"text","la":"Gaudéte in Dómino semper: íterum dico, gaudéte. Modéstia vestra nota sit ómnibus homínibus: Dóminus enim prope est. Nihil sollíciti sitis: sed in omni oratióne petitiónes vestræ innotéscant apud Deum."},{"k":"ref","la":"Ps 84:2"},{"k":"text","la":"Benedixísti, Dómine, terram tuam: avertísti captivitátem Jacob."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Gaudéte in Dómino semper: íterum dico, gaudéte. Modéstia vestra nota sit ómnibus homínibus: Dóminus enim prope est. Nihil sollíciti sitis: sed in omni oratióne petitiónes vestræ innotéscant apud Deum."}],"Oratio":[{"k":"text","la":"Aurem tuam, quǽsumus, Dómine, précibus nostris accómmoda: et mentis nostræ ténebras, grátia tuæ visitatiónis illústra:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Lectio Epístolæ beáti Pauli Apóstoli ad Philippénses"},{"k":"ref","la":"Philipp 4:4-7"},{"k":"text","la":"Fratres: Gaudéte in Dómino semper: íterum dico, gaudéte. Modéstia vestra nota sit ómnibus homínibus: Dóminus prope est. Nihil sollíciti sitis: sed in omni oratióne et obsecratióne, cum gratiárum actióne, petitiónes vestræ innotéscant apud Deum. Et pax Dei, quæ exsúperat omnem sensum, custódiat corda vestra et intellegéntias vestras, in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 79:2; 79:3; 79:2"},{"k":"text","la":"Qui sedes, Dómine, super Chérubim, éxcita poténtiam tuam, et veni."},{"k":"text","la":"Qui regis Israël, inténde: qui dedúcis, velut ovem, Joseph. Allelúja, allelúja,","mark":"V"},{"k":"text","la":"Excita, Dómine, potentiam tuam, et veni, ut salvos fácias nos. Allelúja.","mark":"V"}],"GradualeF":[{"k":"ref","la":"Ps 79:2; 79:3; 79:2"},{"k":"text","la":"Qui sedes, Dómine, super Chérubim, éxcita poténtiam tuam, et veni."},{"k":"text","la":"Qui regis Israël, inténde: qui dedúcis, velut ovem, Joseph.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 1:19-28"},{"k":"text","la":"In illo tempore: Misérunt Judǽi ab Jerosólymis sacerdótes et levítas ad Joánnem, ut interrogárent eum: Tu quis es? Et conféssus est, et non negávit: et conféssus est: Quia non sum ego Christus. Et interrogavérunt eum: Quid ergo? Elías es tu? Et dixit: Non sum. Prophéta es tu? Et respondit: Non. Dixérunt ergo ei: Quis es, ut respónsum demus his, qui misérunt nos? Quid dicis de te ipso? Ait: Ego vox clamántis in desérto: Dirígite viam Dómini, sicut dixit Isaías Prophéta. Et qui missi fúerant, erant ex pharisǽis. Et interrogavérunt eum, et dixérunt ei: Quid ergo baptízas, si tu non es Christus, neque Elías, neque Prophéta? Respóndit eis Joánnes, dicens: Ego baptízo in aqua: médius autem vestrum stetit, quem vos nescítis. Ipse est, qui post me ventúrus est, qui ante me factus est: cujus ego non sum dignus ut solvam ejus corrígiam calceaménti. Hæc in Bethánia facta sunt trans Jordánem, ubi erat Joánnes baptízans."}],"Offertorium":[{"k":"ref","la":"Ps 84:2"},{"k":"text","la":"Benedixísti, Dómine, terram tuam: avertísti captivitátem Jacob: remisísti iniquitatem plebis tuæ."}],"Secreta":[{"k":"text","la":"Devotiónis nostræ tibi, quǽsumus, Dómine, hóstia júgiter immolétur: quæ et sacri péragat institúta mystérii, et salutáre tuum in nobis mirabíliter operétur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Is 35:4"},{"k":"text","la":"Dícite: pusillánimes, confortámini et nolíte timére: ecce, Deus noster véniet et salvábit nos."}],"Postcommunio":[{"k":"text","la":"Implorámus, Dómine, cleméntiam tuam: ut hæc divína subsídia, a vítiis expiátos, ad festa ventúra nos prǽparent."},{"k":"macro","name":"Per Dominum"}]},"hr":{"bf9c459b71ffc019":{"t":"Fil 4, 4-6, Ps 84, 2\n(Fil 4, 4-6) Radujte se u Gospodinu uvijek! Opet kažem: Radujte se! Neka vašu blagost upoznaju svi ljudi! Gospodin je blizu. Nemojte se ni za što tjeskobno brinuti, nego svoje molbe iznosite Bogu u molitvi sa zahvalom. (Ps 84, 2) Blagoslovio si, Gospodine, svoju zemlju, izveo si Jakova iz ropstva.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Fil 4, 4-6) Radujte se u Gospodinu uvijek! Opet kažem: Radujte se! Neka vašu blagost upoznaju svi ljudi! Gospodin je blizu. Nemojte se ni za što tjeskobno brinuti, nego svoje molbe iznosite Bogu u molitvi sa zahvalom."},"a942b999483e8941":{"t":"<i>Pomolimo se</i>.\nPrikloni, molimo, Gospodine, svoje uho k našim molitvama i milošću svoga pohoda rasvijetli tmine naše pameti:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"e58cff9ad43a2f25":{"t":"Fil 4, 4-7\nČitanje Poslanice bl. Pavla apostola Filipljanima. Braćo: radujte se u Gospodinu uvijek! Opet kažem: Radujte se! Neka vašu blagost upoznaju svi ljudi! Gospodin je blizu! Nemojte se ni za što tjeskobno brinuti, nego svoje molbe iznosite Bogu u molitvi i prošnji sa zahvalom. I Božji mir, koji nadilazi svaki um, neka čuva vaša srca i vaše misli u našem Gospodinu Isusu Kristu."},"7a3ce3d99e29f2cc":{"t":"Ps 79, 2-3\nGospodine, koji stoluješ nad kerubinima, probudi svoju moć i dođi. Čuj, vladaru Izraelov, koji vodiš Josipovo pleme kao stado."},"779a38164e993bd1":{"t":"Iv 1, 19-28\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme pošalju Židovi iz Jeruzalema svećenike i levite k Ivanu da ga pitaju: »Tko si ti?« On prizna, ne zataji nego prizna: »Ja nisam Krist.« Kažu mu: »Onda što si, jesi li Ilija?« Reče: »Nisam.« »Jesi li prorok?« Odgovori: »Ne.« Tada mu reknu: »Pa tko si, da odgovorimo onima koji su nas poslali. Što kažeš o sebi?« On reče: »Ja sam glas onoga koji viče u pustinji: Poravnite put Gospodinu, kao što reče prorok Izaija.« – Poslanici su bili farizeji i još ga upitaju: »Zašto onda krstiš, kad nisi ni Krist, ni Ilija, ni prorok?« Ivan im odgovori: »Ja krstim vodom, a među vama stoji onaj koga vi ne poznajete. On dolazi poslije mene, a bio je prije mene. Njemu ja nisam dostojan odriješiti remena na obući.« Ovo se dogodilo u Betaniji s onu stranu Jordana, gdje je Ivan krstio."},"78a95a7d0701477c":{"t":"Ps 84, 2\nBlagoslovio si, Gospodine, svoju zemlju. Izveo si Jakova iz ropstva, oprostio si krivicu narodu svojemu."},"122d6d50c3548655":{"t":"Molimo te, Gospodine, da ti u odanosti uvijek prinosimo darove po kojima neka se izvrši uredba svete tajne i u nama proizvede djelo tvoga spasenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"63277cf92755bc53":{"t":"Iz 35, 4\nRecite: Malodušni, ohrabrite se i nemojte se bojati. Evo, Bog će naš doći i spasit će nas."},"8a38a9dbd4894cf0":{"t":"<i>Pomolimo se</i>.\nZazivamo, Gospodine, tvoju blagost, da nas, očišćene od mana, ova božanska pomoć pripravi na skore blagdane.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
